 "content": "def transform(grid):
    g=[r[:] for r in grid]
    R,C=len(g),len(g[0])
    # Find rows containing horizontal runs. Fill holes; each hole's column is
    # a vertical channel, colored by the segment adjacent to it on that row.
    bars=[]
    for r,row in enumerate(g):
        cols=[c for c,v in enumerate(row) if v]
        if len(cols)>=3:
            # segments are contiguous blocks; use color at left of each gap
            bars.append(r)
    # Each horizontal row is filled across its own extent. Vertical missing
    # columns are projected upwards, using that row's color at that column's
    # nearest horizontal segment (nearest nonzero cell).
    for r in bars:
        cols=[c for c,v in enumerate(g[r]) if v]
        lo,hi=min(cols),max(cols)
        for c in range(lo,hi+1):
            if g[r][c]==0:
                # color from closest neighbor; tie prefers left
                d=1
                while c-d>=lo and c+d<=hi and g[r][c-d]==0 and g[r][c+d]==0: d+=1
                g[r][c]=g[r][c-d] if c-d>=lo and g[r][c-d] else g[r][c+d]
    # For isolated vertical markers below lowest stripe, their columns
    # identify channels to extend: color from the horizontal stripe above.
    if bars:
        base=bars[0]
        for r in bars:
            for c in range(C):
                # any lower vertical line at this position, ignoring other bars
                if any(grid[rr][c] for rr in range(r+1,R)) and all(grid[rr][c]==0 for rr in range(r+1,R) if rr not in bars):
                    if grid[r][c]: col=grid[r][c]
                    else:
                        # nearest original horizontal cell
                        col=next((grid[r][x] for x in range(c-1,-1,-1) if grid[r][x]),0)
                    for rr in range(r):
                        if g[rr][c]==0: g[rr][c]=col
    return g
