def transform(grid):
    # The horizontal stripes are broken at the columns of lower vertical bars.
    # Complete each break and extend that stripe color upward until it meets
    # another stripe; rows below the stripes are unchanged.
    g=[row[:] for row in grid]
    bars=[]
    for r,row in enumerate(grid):
        cols=[c for c,v in enumerate(row) if v]
        if len(cols)>=3:
            bars.append((r,cols[0],cols[-1]))
    for i,(r,left,right) in enumerate(bars):
        top=bars[i-1][0]+1 if i else 0
        row=grid[r]
        for c in range(left,right+1):
            if row[c]==0:
                # extend the stripe's color across the notch
                color=row[next(x for x in range(c-1,left-1,-1) if row[x])]
                for rr in range(top,r+1):
                    g[rr][c]=color
    return g
