def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    stripes=[]
    for r,row in enumerate(grid):
        cols=[c for c,v in enumerate(row) if v]
        if len(cols)>=3:
            stripes.append(r)
    # Each blank within a stripe's horizontal extent launches a vertical ray
    # upward, ending immediately before the preceding horizontal stripe.
    for i,r in enumerate(stripes):
        top=stripes[i-1]+1 if i else 0
        row=grid[r]
        cols=[c for c,v in enumerate(row) if v]
        color=row[cols[0]]
        for c in range(cols[0],cols[-1]+1):
            if row[c]==0:
                for rr in range(top,r+1):
                    g[rr][c]=color
    return g
