def transform(grid):
    g=[row[:] for row in grid]
    # Complete each horizontal stripe's holes and project them upward. Earlier
    # rays/stripes block later ones, so process stripe rows top to bottom.
    for r,row in enumerate(grid):
        cols=[c for c,v in enumerate(row) if v]
        if len(cols)<3:
            continue
        color=row[cols[0]]
        for c in range(cols[0],cols[-1]+1):
            if row[c]!=0:
                continue
            g[r][c]=color
            for rr in range(r-1,-1,-1):
                if g[rr][c]!=0:
                    break
                g[rr][c]=color
    return g
